<?php

namespace rondodevs\toolkit\support;

use Craft;

/**
 * Signs Craft's requests to the frontend's cache API (purges, stats, health), so the frontend
 * needs no shared secret: it fetches the public key from Craft once and checks the signature.
 *
 * The Ed25519 key pair is derived from Craft's security key (CRAFT_SECURITY_KEY, generated by
 * Coolify): nothing to configure, the same on every web and worker container, and it changes only
 * if the security key does. The private key never leaves Craft.
 *
 * Signed: `v1\n{timestamp}\n{METHOD}\n{path?query}\n{sha256(body)}`, in the headers below. The
 * frontend (layer-craft, server/utils/cacheApiAuth) refuses a timestamp more than 5 minutes off.
 */
final class RequestSigner
{
    public const VERSION = 'v1';
    public const HEADER_SIGNATURE = 'x-toolkit-signature';
    public const HEADER_TIMESTAMP = 'x-toolkit-timestamp';
    // the seed is the security key's HMAC on this label: another label, another key pair
    private const SEED_LABEL = 'craft-toolkit:cache-api:ed25519';

    private static ?string $keyPair = null;

    /**
     * The headers to add to a request to the frontend.
     *
     * @return array<string, string>
     */
    public static function headers(string $method, string $url, string $body = ''): array
    {
        $timestamp = (string)time();
        $signature = sodium_crypto_sign_detached(
            self::payload($timestamp, $method, $url, $body),
            sodium_crypto_sign_secretkey(self::keyPair()),
        );

        return [
            self::HEADER_TIMESTAMP => $timestamp,
            self::HEADER_SIGNATURE => base64_encode($signature),
        ];
    }

    /** The public key, base64: served to the frontend by actions/toolkit/cache-api/public-key */
    public static function publicKey(): string
    {
        return base64_encode(sodium_crypto_sign_publickey(self::keyPair()));
    }

    private static function payload(string $timestamp, string $method, string $url, string $body): string
    {
        $path = (string)(parse_url($url, PHP_URL_PATH) ?: '/');
        $query = parse_url($url, PHP_URL_QUERY);

        return implode("\n", [
            self::VERSION,
            $timestamp,
            strtoupper($method),
            $query ? "$path?$query" : $path,
            hash('sha256', $body),
        ]);
    }

    private static function keyPair(): string
    {
        if (self::$keyPair === null) {
            $securityKey = (string)Craft::$app->getConfig()->getGeneral()->securityKey;

            if ($securityKey === '') {
                throw new \RuntimeException('Craft has no security key (CRAFT_SECURITY_KEY): requests to the frontend cannot be signed.');
            }

            self::$keyPair = sodium_crypto_sign_seed_keypair(hash_hmac('sha256', self::SEED_LABEL, $securityKey, true));
        }

        return self::$keyPair;
    }
}
